() => {
  const text = document.body.innerText;
  const geminiMatches = text.match(/Gemini/gi) || [];
  // check auth state
  let authInfo = null;
  try {
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (k && (k.includes('auth') || k.includes('user') || k.includes('token'))) {
        authInfo = { key: k, value: (localStorage.getItem(k) || '').slice(0, 300) };
      }
    }
  } catch(e) {}
  return {
    hasGemini: geminiMatches.length > 0,
    geminiCount: geminiMatches.length,
    authInfo,
    url: location.href
  };
}

() => {
  const text = document.body.innerText;
  const matches = text.match(/Gemini/gi) || [];
  // also check empty-state area text if present
  const hasEmptyState = text.includes('暂无已生成的报表');
  return { hasGemini: matches.length > 0, geminiCount: matches.length, hasEmptyStateReports: hasEmptyState };
}

