() => {
  const els = [...document.querySelectorAll('*')].filter(e => e.children.length === 0 && e.textContent.includes('NL2SQL 引擎'));
  if (els.length) {
    els[0].scrollIntoView({ block: 'center' });
    // also scroll inner main container if needed
    return { found: true, text: els[0].textContent.trim() };
  }
  return { found: false };
}
